:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --accent-dark: #b83a4f;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
  --success: #4ecca3;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.02) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(255,255,255,0.02) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(255,255,255,0.02) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(255,255,255,0.02) 75%);
  background-size: 16px 16px;
  background-position: 0 0, 0 8px, 8px -8px, -8px 0;
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
}

.card {
  width: 100%;
  max-width: 420px;
  background: var(--card);
  border: 4px solid var(--border);
  box-shadow: 8px 8px 0 var(--border), 0 0 0 4px var(--bg);
  padding: 28px 24px 20px;
  image-rendering: pixelated;
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 0.5px;
  margin-bottom: 6px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 var(--border);
  line-height: 1.2;
}

.subtitle {
  font-size: 0.95rem;
  color: var(--muted);
  margin-bottom: 24px;
}

.form {
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text);
  letter-spacing: 0.3px;
}

.input-wrap {
  display: flex;
  align-items: center;
  background: var(--bg);
  border: 3px solid var(--border);
  transition: border-color 0.1s, box-shadow 0.1s;
}

.input-wrap:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 2px var(--accent);
}

.prefix, .suffix {
  padding: 0 10px;
  color: var(--muted);
  font-weight: 600;
  font-size: 0.95rem;
  user-select: none;
}

input[type="number"] {
  flex: 1;
  min-width: 0;
  padding: 12px 8px;
  background: transparent;
  border: none;
  color: var(--text);
  font-size: 1rem;
  font-family: var(--font);
  outline: none;
  -moz-appearance: textfield;
}

input[type="number"]::-webkit-outer-spin-button,
input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

input::placeholder {
  color: var(--muted);
  opacity: 0.6;
}

.actions {
  display: flex;
  gap: 12px;
  margin-top: 4px;
  flex-wrap: wrap;
}

.btn {
  flex: 1 1 auto;
  min-width: 120px;
  padding: 14px 16px;
  font-size: 1rem;
  font-weight: 700;
  font-family: var(--font);
  letter-spacing: 0.5px;
  text-transform: uppercase;
  border: 3px solid transparent;
  cursor: pointer;
  transition: transform 0.08s, box-shadow 0.08s, background 0.15s, border-color 0.15s;
  box-shadow: 4px 4px 0 var(--border);
}

.btn.primary {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent-dark);
}

.btn.primary:hover {
  background: #f05a72;
}

.btn.secondary {
  background: transparent;
  color: var(--text);
  border-color: var(--border);
}

.btn.secondary:hover {
  background: var(--border);
}

.btn:focus-visible {
  outline: none;
  box-shadow: 4px 4px 0 var(--border), 0 0 0 3px var(--accent);
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 var(--border);
}

.error {
  margin-top: 16px;
  padding: 10px 12px;
  border: 3px solid var(--accent);
  background: rgba(233, 69, 96, 0.12);
  color: #ffb3c1;
  font-size: 0.95rem;
  line-height: 1.4;
}

.results {
  margin-top: 22px;
  border-top: 3px dashed var(--border);
  padding-top: 16px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.result-row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 12px;
  flex-wrap: wrap;
}

.result-label {
  font-size: 0.95rem;
  color: var(--muted);
}

.result-value {
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--success);
  font-variant-numeric: tabular-nums;
  text-shadow: 1px 1px 0 var(--border);
}

#pixel-decor {
  display: block;
  width: 100%;
  height: auto;
  margin-top: 20px;
  image-rendering: pixelated;
}

@media (max-width: 400px) {
  .card {
    padding: 22px 18px 16px;
    box-shadow: 5px 5px 0 var(--border), 0 0 0 3px var(--bg);
  }
  h1 {
    font-size: 1.3rem;
  }
  .btn {
    min-width: 100px;
  }
}

(function () {
  'use strict';

  const form = document.getElementById('loan-form');
  const amountInput = document.getElementById('amount');
  const rateInput = document.getElementById('rate');
  const yearsInput = document.getElementById('years');
  const errorEl = document.getElementById('error');
  const resultsEl = document.getElementById('results');
  const monthlyEl = document.getElementById('monthly');
  const totalPaidEl = document.getElementById('total-paid');
  const totalInterestEl = document.getElementById('total-interest');
  const resetBtn = document.getElementById('reset-btn');

  function fmt(n) {
    return '$' + n.toFixed(2);
  }

  function showError(msg) {
    errorEl.textContent = msg;
    errorEl.hidden = false;
    resultsEl.hidden = true;
  }

  function clearError() {
    errorEl.hidden = true;
    errorEl.textContent = '';
  }

  function calculate() {
    clearError();

    const amount = parseFloat(amountInput.value);
    const rate = parseFloat(rateInput.value);
    const years = parseFloat(yearsInput.value);

    if (!isFinite(amount) || amount <= 0) {
      showError('Enter a loan amount greater than 0.');
      return;
    }
    if (!isFinite(rate) || rate < 0) {
      showError('Enter an interest rate of 0 or more.');
      return;
    }
    if (!isFinite(years) || years <= 0) {
      showError('Enter a loan term greater than 0 years.');
      return;
    }

    const n = Math.round(years * 12);
    if (n <= 0) {
      showError('Loan term is too short.');
      return;
    }

    let monthly;
    if (rate === 0) {
      monthly = amount / n;
    } else {
      const r = rate / 100 / 12;
      const factor = Math.pow(1 + r, n);
      monthly = amount * r * factor / (factor - 1);
    }

    if (!isFinite(monthly) || monthly <= 0) {
      showError('Could not compute a valid payment. Check your inputs.');
      return;
    }

    const totalPaid = monthly * n;
    const totalInterest = totalPaid - amount;

    monthlyEl.textContent = fmt(monthly);
    totalPaidEl.textContent = fmt(totalPaid);
    totalInterestEl.textContent = fmt(totalInterest);
    resultsEl.hidden = false;
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    calculate();
  });

  resetBtn.addEventListener('click', function () {
    form.reset();
    clearError();
    resultsEl.hidden = true;
    amountInput.focus();
  });

  // Pixel decoration: draw small blocks on canvas
  const canvas = document.getElementById('pixel-decor');
  if (canvas && canvas.getContext) {
    const ctx = canvas.getContext('2d');
    const colors = ['#e94560', '#0f3460', '#4ecca3', '#16213e', '#a0a0b0'];
    const size = 8;
    for (let x = 0; x < canvas.width; x += size) {
      for (let y = 0; y < canvas.height; y += size) {
        if (Math.random() > 0.55) {
          ctx.fillStyle = colors[Math.floor(Math.random() * colors.length)];
          ctx.fillRect(x, y, size, size);
        }
      }
    }
  }
})();
